def seed_assessments_db(cursor):
    """Seed or update the 121 assessments and their question banks in the database."""
    import json
    import logging
    logger = logging.getLogger(__name__)

    # Add columns if missing in assessments table
    try:
        cursor.execute("SHOW COLUMNS FROM assessments LIKE 'domain'")
        if not cursor.fetchone():
            cursor.execute("ALTER TABLE assessments ADD COLUMN domain VARCHAR(100) DEFAULT 'technical'")
    except Exception as e:
        logger.debug(f"Column check notice: {e}")

    try:
        cursor.execute("SHOW COLUMNS FROM assessments LIKE 'rating'")
        if not cursor.fetchone():
            cursor.execute("ALTER TABLE assessments ADD COLUMN rating DECIMAL(3,2) DEFAULT 4.85")
    except Exception as e:
        logger.debug(f"Column check notice: {e}")

    try:
        cursor.execute("SHOW COLUMNS FROM assessments LIKE 'is_popular'")
        if not cursor.fetchone():
            cursor.execute("ALTER TABLE assessments ADD COLUMN is_popular TINYINT(1) DEFAULT 0")
    except Exception as e:
        logger.debug(f"Column check notice: {e}")

    try:
        cursor.execute("SHOW COLUMNS FROM assessments LIKE 'is_new'")
        if not cursor.fetchone():
            cursor.execute("ALTER TABLE assessments ADD COLUMN is_new TINYINT(1) DEFAULT 0")
    except Exception as e:
        logger.debug(f"Column check notice: {e}")

    for item in ASSESSMENTS_DATA:
        cursor.execute("SELECT id FROM assessments WHERE category = %s OR title = %s LIMIT 1", (item['category'], item['title']))
        row = cursor.fetchone()
        
        is_pop = 1 if item.get('category') in ['Python', 'SQL', 'React', 'JavaScript', 'AWS', 'Data Analytics', 'Excel', 'Machine Learning', 'Docker', 'System Design'] else 0
        is_nw = 1 if item.get('category') in ['Generative AI', 'TypeScript', 'Next.js', 'Tailwind CSS', 'Kubernetes', 'Cybersecurity Fundamentals'] else 0
        rating = 4.90 if is_pop else (4.85 if is_nw else 4.80)

        if not row:
            cursor.execute("""
                INSERT INTO assessments 
                (title, category, domain, difficulty, description, time_limit_minutes, passing_score, questions_count, icon, badge_icon, rating, is_popular, is_new)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (
                item['title'], item['category'], item['domain'], item['difficulty'],
                item['description'], item['time_limit_minutes'], item['passing_score'],
                len(item['questions']), item['icon'], item['badge_icon'], rating, is_pop, is_nw
            ))
            test_id = cursor.lastrowid
        else:
            test_id = row['id'] if isinstance(row, dict) else row[0]
            cursor.execute("""
                UPDATE assessments 
                SET title = %s, category = %s, domain = %s, difficulty = %s, description = %s, 
                    time_limit_minutes = %s, passing_score = %s, questions_count = %s, icon = %s, badge_icon = %s,
                    rating = %s, is_popular = %s, is_new = %s
                WHERE id = %s
            """, (
                item['title'], item['category'], item['domain'], item['difficulty'],
                item['description'], item['time_limit_minutes'], item['passing_score'],
                len(item['questions']), item['icon'], item['badge_icon'], rating, is_pop, is_nw, test_id
            ))
        
        # Check questions count
        cursor.execute("SELECT COUNT(*) AS cnt FROM assessment_questions WHERE assessment_id = %s", (test_id,))
        q_count_res = cursor.fetchone()
        q_cnt = q_count_res['cnt'] if isinstance(q_count_res, dict) else q_count_res[0]
        if q_cnt == 0:
            for idx, q in enumerate(item['questions'], 1):
                cursor.execute("""
                    INSERT INTO assessment_questions 
                    (assessment_id, question_text, options, correct_option, explanation, question_order)
                    VALUES (%s, %s, %s, %s, %s, %s)
                """, (
                    test_id, q['text'], json.dumps(q['options']), q['correct'], q['explanation'], idx
                ))
